import json, os
base="/Users/applelevne/Documents/coding-projects/language_duel/reports/quality"

def summarize(path, label):
    print("\n====", label, path, "size", os.path.getsize(path))
    with open(path) as f:
        data=json.load(f)
    if isinstance(data, dict):
        print("top keys:", list(data.keys())[:40])
        # print compact non-huge fields
        for k,v in data.items():
            if k in ("functions","files","perFunction","sourceFiles"): 
                if isinstance(v, list):
                    print(f"  {k}: list len {len(v)}")
                elif isinstance(v, dict):
                    print(f"  {k}: dict len {len(v)}")
                continue
            if isinstance(v, (str,int,float,bool)) or v is None:
                print(f"  {k}: {v}")
            elif isinstance(v, dict) and len(json.dumps(v))<4000:
                print(f"  {k}: {json.dumps(v)[:3000]}")
            elif isinstance(v, list) and len(json.dumps(v))<2000:
                print(f"  {k}: {json.dumps(v)[:1500]}")
            elif isinstance(v, dict):
                print(f"  {k}: dict keys {list(v.keys())[:30]} ...")
            elif isinstance(v, list):
                print(f"  {k}: list len {len(v)}")
    else:
        print(type(data), len(data) if hasattr(data,'__len__') else '')

for p,l in [
    ("current-metrics.json","CURRENT"),
    ("istanbul-metrics.json","ISTANBUL"),
    ("fresh-baseline-metrics.json","FRESH"),
    ("current-tests.json","TESTS"),
]:
    summarize(os.path.join(base,p), l)
