import json, os
from datetime import datetime
base="/Users/applelevne/Documents/coding-projects/language_duel/reports/quality"

def comp_summary(path):
    with open(path) as f:
        data=json.load(f)
    print("\nFILE", os.path.basename(path), "generated", data.get("generatedAt"), "passes", data.get("passes"), "fresh", data.get("coverageFresh"), "missing", data.get("missingFiles"), "changed", len(data.get("changedSinceCoverage") or []))
    comps=data["components"]
    for name,c in comps.items():
        keys=list(c.keys())
        # print compact numeric fields
        interesting={k:c[k] for k in c if not isinstance(c[k], (list, dict))}
        print(f"  {name}: {json.dumps(interesting, default=str)[:800]}")
        # nested totals
        for k,v in c.items():
            if isinstance(v, dict) and len(json.dumps(v))<1500:
                print(f"    {k}: {json.dumps(v)[:1200]}")

for p in ["fresh-baseline-metrics.json","current-metrics.json","istanbul-metrics.json"]:
    comp_summary(os.path.join(base,p))

print("\n=== file mtimes ===")
for name in ["current-tests.json","current-tests.log","current-metrics.json","istanbul-metrics.json","quality-check.exit","typecheck.log","PROGRESS.md"]:
    p=os.path.join(base,name)
    if os.path.exists(p):
        st=os.stat(p)
        print(name, datetime.fromtimestamp(st.st_mtime).isoformat(), "size", st.st_size)
print("--- batches mtimes ---")
for i in range(1,38):
    p=os.path.join(base, f"batch-{i:02d}.log")
    if os.path.exists(p):
        st=os.stat(p)
        print(f"batch-{i:02d}", datetime.fromtimestamp(st.st_mtime).isoformat(), "size", st.st_size)
