import { useEffect, useRef, useState } from "react";

interface UseDuelCountdownArgs {
  phase: "idle" | "answering" | "transition";
  duelStatus: string;
  countdownPausedBy?: string;
  countdownSkipRequestedBy: string[];
  onCountdownComplete: () => void;
}

export function useDuelCountdown({
  phase,
  duelStatus,
  countdownPausedBy,
  countdownSkipRequestedBy,
  onCountdownComplete,
}: UseDuelCountdownArgs) {
  const [countdown, setCountdown] = useState<number | null>(null);
  const prevCountdownPausedByRef = useRef<string | undefined>(countdownPausedBy);

  useEffect(() => {
    const wasPaused = prevCountdownPausedByRef.current;
    const isNowUnpaused = !countdownPausedBy;

    if (wasPaused && isNowUnpaused && countdown !== null && phase === "transition") {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- countdown reset is the transition event we are syncing to.
      setCountdown(1);
    }

    prevCountdownPausedByRef.current = countdownPausedBy;
  }, [countdownPausedBy, countdown, phase]);

  useEffect(() => {
    if (countdown === null || phase !== "transition") return;
    if (countdownPausedBy) return;

    if (countdown > 0) {
      const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
      return () => clearTimeout(timer);
    }

    if (duelStatus !== "completed") {
      onCountdownComplete();
    }
    // eslint-disable-next-line react-hooks/set-state-in-effect -- state machine transition endpoint, not derived render state.
    setCountdown(null);
  }, [countdown, duelStatus, countdownPausedBy, phase, onCountdownComplete]);

  useEffect(() => {
    if (countdown === null || countdown === 0 || phase !== "transition") return;
    if (countdownSkipRequestedBy.includes("challenger") && countdownSkipRequestedBy.includes("opponent")) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- both-player skip should immediately collapse the countdown.
      setCountdown(0);
    }
  }, [countdownSkipRequestedBy, countdown, phase]);

  return { countdown, setCountdown };
}

import { ConvexError } from "convex/values";
import type { Doc, Id } from "../_generated/dataModel";
import { MIN_GOAL_DURATION_MS } from "../constants";
import {
  canEditGoalEndDate,
  countCompletedThemes,
  getEffectiveBigBossStatus,
  getEffectiveGoalStatus,
  getEffectiveMiniBossStatus,
  normalizeWeeklyGoal,
  type NormalizedWeeklyGoal,
  type WeeklyGoalLockState,
} from "../../lib/weeklyGoals";
import type { GoalRole, GoalWithUsers } from "./types";
import { toUserSummary } from "../helpers/userSummary";

export function shouldIncludeGoal(
  goal: Doc<"weeklyGoals">,
  now: number
): boolean {
  // getEffectiveGoalStatus is the single lifecycle truth: a goal is visible
  // until it is completed. Past-grace deletion is handled by the cron, whose
  // index predicate (cleanup.ts) needs the raw arithmetic because it runs
  // before this reclassification would apply.
  return getEffectiveGoalStatus(goal, now) !== "completed";
}

/**
 * Derive the viewer-relative lock view once, so no client read path has to
 * re-implement the role↔lock mapping from the raw creator/partner booleans.
 */
function deriveLockState(
  goal: NormalizedWeeklyGoal<Doc<"weeklyGoals">>,
  viewerRole: GoalRole
): WeeklyGoalLockState {
  const locks = {
    creator: goal.creatorLocked,
    partner: goal.mode === "shared" && goal.partnerLocked,
  };
  const viewerLocked = locks[viewerRole];
  const partnerLocked = locks[viewerRole === "creator" ? "partner" : "creator"];

  if (viewerLocked && partnerLocked) return "both_locked";
  if (viewerLocked) return "viewer_locked";
  if (partnerLocked) return "partner_locked";
  return "none";
}

export function buildGoalWithUsers(
  goal: Doc<"weeklyGoals">,
  usersById: Map<Id<"users">, Doc<"users"> | null>,
  viewerRole: GoalRole,
  now: number
): GoalWithUsers {
  const normalizedGoal = normalizeWeeklyGoal(goal);
  const miniBossStatus = getEffectiveMiniBossStatus(normalizedGoal, now);
  const bigBossStatus = getEffectiveBigBossStatus(normalizedGoal, now);
  const effectiveViewerRole = normalizedGoal.mode === "solo" ? "creator" : viewerRole;
  const partnerId = goal.partnerId;

  return {
    goal: normalizedGoal,
    mode: normalizedGoal.mode,
    creator: toUserSummary(usersById.get(goal.creatorId) ?? null),
    partner: normalizedGoal.mode === "solo" || partnerId === undefined
      ? null
      : toUserSummary(usersById.get(partnerId) ?? null),
    viewerRole: effectiveViewerRole,
    lockState: deriveLockState(normalizedGoal, effectiveViewerRole),
    effectiveStatus: getEffectiveGoalStatus(normalizedGoal, now),
    miniBossStatus,
    bigBossStatus,
    completedThemeCount: countCompletedThemes(normalizedGoal.themes, normalizedGoal.mode),
    canEditEndDate: canEditGoalEndDate(normalizedGoal, now),
  };
}

